private _vioc_nar_sog = missionNamespace getVariable ["CTI_SOG_DLC", 0];
private _vioc_nar_modern = !((_vioc_nar_gm isEqualType 0 && {_vioc_nar_gm > 1}) || {_vioc_nar_sog isEqualType 0 && {_vioc_nar_sog > 1}});
private _vioc_nar_chdkz = missionNamespace getVariable ["CTI_CHDKZ_SIDE", -1];
VIOC_NARCO_ON = _vioc_nar_modern && {_vioc_nar_chdkz isEqualType 0} && {_vioc_nar_chdkz >= 0} && {(VIOC_NARCO_STYLE == 2) || {VIOC_NARCO_STYLE == 1 && {(toLower worldName) in VIOC_TG_WORLDS}}};
