	["sniper", [["CUP_srifle_SVD", 1], ["CUP_srifle_Remington700", 0.5], ["CUP_srifle_CZ550_rail", 1]]],
	["lat", [["CUP_launch_RPG18_Loaded", 2], ["rhs_weap_rpg18", 1], ["CUP_launch_M72A6_Loaded", 1.5], ["rhs_weap_m72a7", 0.5]]],
	["at", [["CUP_launch_RPG7V", 3], ["rhs_weap_rpg7", 2]]],
	["aa", [["CUP_launch_9K32Strela_Loaded", 2], ["CUP_launch_Igla_Loaded", 1]]],
	["pistol", [["CUP_hgun_Makarov", 1], ["CUP_hgun_Colt1911", 1.5], ["CUP_hgun_Glock17_blk", 1.5], ["CUP_hgun_CZ75", 1], ["CUP_hgun_TT", 1], ["rhsusf_weap_m1911a1", 0.5], ["CUP_hgun_M9", 0.5]]]
];
//--- Operaciones especiales (VIOC_specops): pares [clave, valor] de cada paquete
VIOC_NARCO_DATA_SO = [
	[["id", "NAR_SICARIOS"], ["name", "Sicarios del cartel"], ["nation", "CHDKZ"], ["mod", "RHSL"], ["camo", []], ["types", ["raid", "heli"]], ["lead", ["rhsgref_ins_commander"]], ["units", ["rhsgref_ins_rifleman_aksu", "rhsgref_ins_rifleman_aksu", "rhsgref_ins_rifleman_akm", "rhsgref_ins_rifleman", "rhsgref_ins_arifleman_rpk", "rhsgref_ins_grenadier_rpg", "rhsgref_ins_machinegunner", "rhsgref_ins_medic"]], ["night", []], ["planes", []], ["helis", ["CUP_O_UH1H_slick_SLA", "rhsgref_ins_Mi8amt"]], ["chute", ["rhs_d6_Parachute", "NonSteerable_Parachute_F"]], ["nvg", ""], ["supp", false], ["bonus", 0.05], ["w", 2]],
	[["id", "NAR_SELVA"], ["name", "Comando de selva de la insurgencia"], ["nation", "CHDKZ"], ["mod", "RHSL"], ["camo", []], ["types", ["raid", "heli"]], ["lead", ["rhsgref_ins_squadleader"]], ["units", ["rhsgref_ins_saboteur", "rhsgref_ins_saboteur", "rhsgref_ins_grenadier_rpg", "rhsgref_ins_machinegunner", "rhsgref_ins_sniper", "rhsgref_ins_spotter", "rhsgref_ins_medic", "rhsgref_ins_engineer"]], ["night", []], ["planes", []], ["helis", ["CUP_O_UH1H_SLA", "rhsgref_ins_Mi8amt"]], ["chute", ["rhs_d6_Parachute", "NonSteerable_Parachute_F"]], ["nvg", ""], ["supp", false], ["bonus", 0.05], ["w", 1]]
];

VIOC_NARCO_fnc_stat = {
	params ["_i", ["_n", 1]];
	VIOC_NARCO_STATUS set [_i, (VIOC_NARCO_STATUS select _i) + _n];
};
VIOC_NARCO_fnc_ok = {
	params ["_c"];
	(_c isEqualType "") && {_c != ""} && {isClass (configFile >> "CfgVehicles" >> _c)}
};
//--- Fabrica (CTI_FACTORY_*) con la que esta declarada una clase (Set_Units), o -1 si no esta declarada
VIOC_NARCO_fnc_fac = {
	params ["_c"];
	if !(_c isEqualType "") exitWith {-1};
	private _d = missionNamespace getVariable _c;
	if (isNil "_d") exitWith {-1};
	if !(_d isEqualType [] && {count _d > 5}) exitWith {-1};
	_d select 5
};
//--- La clase nueva puede ir donde va la vieja: declarada y de la misma fabrica (el menu de compra y la IA usan
//--- la fabrica de los datos de la unidad para el nivel de mejora)
VIOC_NARCO_fnc_same = {
	params ["_new", "_old"];
	private _fn = [_new] call VIOC_NARCO_fnc_fac;
	(_fn isNotEqualTo -1) && {_fn isEqualTo ([_old] call VIOC_NARCO_fnc_fac)}
};
//--- Columna de los datos: 0 = Este/Oeste (_sid ""), 1 = Resistencia (_sid "_g")
VIOC_NARCO_fnc_col = {
	params ["_side"];
	[0, 1] select (_side == resistance)
};
//--- Tablas del bando: anclas -> nuevas, viejas -> nuevas, quitadas (en minusculas)
VIOC_NARCO_fnc_tables = {
	params ["_side"];
	private _k = format ["VIOC_NARCO_T_%1", _side];
	private _t = missionNamespace getVariable [_k, []];
	if (_t isNotEqualTo []) exitWith {_t};
	private _col = [_side] call VIOC_NARCO_fnc_col;
	private _like = createHashMap;	//--- ancla -> [[nueva, mult, pool], ...]
	{
		_x params ["_aE", "_aG", "_news"];
		private _a = [_aE, _aG] select _col;
		private _l = [];
		{
			_x params ["_nE", "_nG", "_m", "_pool"];
			private _n = [_nE, _nG] select _col;
			if ([_n] call VIOC_NARCO_fnc_ok) then {_l pushBack [_n, _m, _pool == 1]};
		} forEach _news;
		if (_a != "" && {_l isNotEqualTo []}) then {_like set [toLower _a, (_like getOrDefault [toLower _a, []]) + _l]};
	} forEach VIOC_NARCO_DATA_LIKE;
	private _repl = createHashMap;	//--- vieja -> [nueva, mult] (solo si la nueva existe)
	{
		_x params ["_oE", "_oG", "_nE", "_nG", "_m"];
		private _o = [_oE, _oG] select _col;
		private _n = [_nE, _nG] select _col;
		if (_o != "" && {[_n] call VIOC_NARCO_fnc_ok}) then {_repl set [toLower _o, [_n, _m]]};
	} forEach VIOC_NARCO_DATA_REPL;
	private _drop = createHashMap;
	{ private _o = (_x select _col); if (_o != "") then {_drop set [toLower _o, true]} } forEach VIOC_NARCO_DATA_DROP;
	_t = [_like, _repl, _drop];
	missionNamespace setVariable [_k, _t];
	_t
};

//--- 1) units_ChDKZ_RHS.sqf, antes de Set_Units: declara las clases nuevas (nivel, fabrica, tiempo y distancia del
//--- ancla; precio del ancla x mult) y las lanchas. No quita nada (las quitadas salen del menu en la fabrica).
VIOC_NARCO_fnc_units = {
	params ["_side", "_c", "_p", "_n", "_o", "_t", "_u", "_f", "_s", "_d"];
	if (!VIOC_NARCO_ON) exitWith {};
	([_side] call VIOC_NARCO_fnc_tables) params ["_like", "_repl"];
	private _col = [_side] call VIOC_NARCO_fnc_col;
	private _add = {
		params ["_i", "_new", "_mult"];
		if ((_c findIf {_x isEqualType "" && {_x == _new}}) >= 0) exitWith {};
		_c pushBack _new; _p pushBack ""; _n pushBack "";
		_o pushBack (round (((_o select _i) * _mult) max 50)); _t pushBack (_t select _i); _u pushBack (_u select _i);
		_f pushBack (_f select _i); _s pushBack ""; _d pushBack (_d select _i);
		[3] call VIOC_NARCO_fnc_stat;
	};
	private _cnt = count _c;
	for "_i" from 0 to (_cnt - 1) do {
		private _cls = _c select _i;
		if (_cls isEqualType "") then {
			private _lc = toLower _cls;
			{ [_i, _x select 0, _x select 1] call _add } forEach (_like getOrDefault [_lc, []]);
			private _r = _repl getOrDefault [_lc, []];
			if (_r isNotEqualTo []) then {[_i, _r select 0, _r select 1] call _add};
		};
	};
	{
		_x params ["_nE", "_nG", "_m"];
		private _cls = [_nE, _nG] select _col;
		if ([_cls] call VIOC_NARCO_fnc_ok && {(_c findIf {_x isEqualType "" && {_x == _cls}}) < 0}) then {
			_c pushBack _cls; _p pushBack ""; _n pushBack "";
			_o pushBack (round (([CTI_ECONOMY_PRIZE_NAVAL, 0] call CTI_CO_FNC_GetCalculatedUnitsPrize) * _m));
			_t pushBack ([CTI_FACTORY_NAVAL, 0] call CTI_CO_FNC_GetCalculatedBuildtime); _u pushBack 0;
			_f pushBack CTI_FACTORY_NAVAL; _s pushBack ""; _d pushBack 10;
			[3] call VIOC_NARCO_fnc_stat;
		};
	} forEach VIOC_NARCO_DATA_NAVAL;
};

//--- 2) factory_ChDKZ_RHS.sqf (al final): menus de las fabricas. Nuevas detras de su ancla (si son de su misma
//--- fabrica); fuera las sustituidas (si la nueva vale) y las quitadas; lanchas en la naval. Las demas entradas del
//--- autor quedan igual y en su orden (tambien las repetidas, como las dos UAZ del deposito).
VIOC_NARCO_fnc_factory = {
	params ["_side"];
	if (!VIOC_NARCO_ON) exitWith {};
	([_side] call VIOC_NARCO_fnc_tables) params ["_like", "_repl", "_drop"];
	private _col = [_side] call VIOC_NARCO_fnc_col;
	private _all = [];
	{
		private _type = _x;
		private _k = format ["CTI_%1_%2Units", _side, _type];
		private _l = missionNamespace getVariable [_k, []];
		if (_l isEqualType []) then {
			private _out = [];
			private _has = {
				params ["_c"];
				((_out findIf {_x isEqualType "" && {_x == _c}}) >= 0) || {(_l findIf {_x isEqualType "" && {_x == _c}}) >= 0}
			};
			{
				private _cls = _x;
				private _lc = if (_cls isEqualType "") then {toLower _cls} else {""};
				private _r = _repl getOrDefault [_lc, []];
				private _rOk = _r isNotEqualTo [] && {[_r select 0, _cls] call VIOC_NARCO_fnc_same};
				if !((_drop getOrDefault [_lc, false]) || {_rOk}) then {_out pushBack _cls};
				if (_rOk && {!([_r select 0] call _has)}) then {_out pushBack (_r select 0)};
				{
					private _nc = _x select 0;
					if ([_nc, _cls] call VIOC_NARCO_fnc_same && {!([_nc] call _has)}) then {_out pushBack _nc};
				} forEach (_like getOrDefault [_lc, []]);
			} forEach _l;
			if (_type == CTI_NAVAL) then {
				{
					private _nc = _x select _col;
					if (_nc != "" && {([_nc] call VIOC_NARCO_fnc_fac) isEqualTo CTI_FACTORY_NAVAL} && {!([_nc] call _has)}) then {_out pushBack _nc};
				} forEach VIOC_NARCO_DATA_NAVAL;
			};
			if (_out isNotEqualTo _l) then {
				[4, (count _out) - (count _l)] call VIOC_NARCO_fnc_stat;
				missionNamespace setVariable [_k, _out];
			};
			_all pushBack _out;
		};
	} forEach [CTI_BARRACKS, CTI_LIGHT, CTI_HEAVY, CTI_AIR, CTI_REPAIR, CTI_AMMO, CTI_DEPOT, CTI_NAVAL];
	missionNamespace setVariable [format ["VIOC_NARCO_AUTHOR_%1", _side], _all];	//--- para VIOC_NARCO_fnc_postAll
};

//--- Un grupo [[clase, n(, prob)], ...] con las sustituciones (en el sitio), las quitadas y, si 'pool', las nuevas
//--- junto a su ancla (mismo n y prob). Solo clases declaradas y de la misma fabrica que la del autor (la compra de
//--- la IA da vueltas sin fin con una clase sin datos). Si quedara vacio, devuelve el original.
VIOC_NARCO_fnc_pool = {
	params ["_pool", "_like", "_repl", "_drop"];
	if !(_pool isEqualType []) exitWith {_pool};
	private _out = [];
	private _has = {
		params ["_c"];
		(_out findIf {(_x select 0) isEqualType "" && {(_x select 0) == _c}}) >= 0
	};
	{
		private _e = _x;
		if (_e isEqualType [] && {count _e > 0} && {(_e select 0) isEqualType ""}) then {
			private _cls = _e select 0;
			private _lc = toLower _cls;
			private _r = _repl getOrDefault [_lc, []];
			if (_r isNotEqualTo [] && {[_r select 0, _cls] call VIOC_NARCO_fnc_same}) then {
				if !([_r select 0] call _has) then {private _ne = +_e; _ne set [0, _r select 0]; _out pushBack _ne};
			} else {
				if !(_drop getOrDefault [_lc, false]) then {_out pushBack _e};
			};
			{
				_x params ["_nc", "", "_inPool"];
				if (_inPool && {[_nc, _cls] call VIOC_NARCO_fnc_same} && {!([_nc] call _has)}) then {private _ne = +_e; _ne set [0, _nc]; _out pushBack _ne};
			} forEach (_like getOrDefault [_lc, []]);
		} else {
			_out pushBack _e;	//--- formato que no es [clase, n(, prob)]: se deja como esta
		};
	} forEach _pool;
	if (_out isEqualTo []) exitWith {_pool};
	_out
};

//--- 3) squad_ChDKZ_RHS.sqf, antes de Squads_Set: grupos de compra de la IA (_p = lista de grupos)
VIOC_NARCO_fnc_squads = {
	params ["_side", "_p"];
	if (!VIOC_NARCO_ON) exitWith {};
	([_side] call VIOC_NARCO_fnc_tables) params ["_like", "_repl", "_drop"];
	for "_i" from 0 to ((count _p) - 1) do {
		private _old = _p select _i;
		private _new = [_old, _like, _repl, _drop] call VIOC_NARCO_fnc_pool;
		if !(_new isEqualTo _old) then {_p set [_i, _new]; [5] call VIOC_NARCO_fnc_stat};
	};
};

//--- 4) towns_ChDKZ_RHS.sqf (al final): grupos de los pueblos que tiene el narco
VIOC_NARCO_fnc_towns = {
	params ["_side", "_tag"];
	if (!VIOC_NARCO_ON) exitWith {};
	([_side] call VIOC_NARCO_fnc_tables) params ["_like", "_repl", "_drop"];
	{
		private _k = _tag + _x;
		private _old = missionNamespace getVariable [_k, []];
		if (_old isEqualType [] && {_old isNotEqualTo []}) then {
			private _new = [_old, _like, _repl, _drop] call VIOC_NARCO_fnc_pool;
			if !(_new isEqualTo _old) then {missionNamespace setVariable [_k, _new]; [6] call VIOC_NARCO_fnc_stat};
		};
	} forEach ["WHEELED_SQ_LIGHT", "WHEELED_SQ_HEAVY", "TRACKED_SQ_LIGHT", "TRACKED_SQ_MEDIUM", "TRACKED_SQ_HEAVY", "AIR_SQ_FIGHTER", "AIR_SQ_BOMBER", "SQ_ANTI_AIR"];
};

//--- 4b) v2: towns_NPoC_CUP.sqf (al final): pueblos de la guerrilla NPoC (Resistencia) sin Hilux raras de CUP, solo con
//--- el estilo narco activo (la mision B). Cada fila [clase, n(, ...)] de una Hilux rara se cambia en el sitio por la
//--- primera candidata de VIOC_NARCO_DATA_GFIX que exista y no este ya en el grupo; si no hay, se quita la fila. Los
//--- pueblos no usan los datos de compra de la clase (no hace falta declararla). Si el grupo quedara vacio, se deja.
VIOC_NARCO_fnc_guerTowns = {
	params ["_side", "_tag"];
	if (!VIOC_NARCO_ON || {_side != resistance} || {!(_tag isEqualType "")}) exitWith {};
	private _fix = createHashMap;
	{ _fix set [toLower (_x select 0), (_x select 1) select {isClass (configFile >> "CfgVehicles" >> _x)}] } forEach VIOC_NARCO_DATA_GFIX;
	{
		private _k = _tag + _x;
		private _old = missionNamespace getVariable [_k, []];
		if (_old isEqualType [] && {_old isNotEqualTo []}) then {
			private _out = [];
			private _nCh = 0;
			private _nDrop = 0;
			{
				private _e = _x;
				private _cls = if (_e isEqualType [] && {count _e > 0} && {(_e select 0) isEqualType ""}) then {_e select 0} else {""};
				private _c = _fix getOrDefault [toLower _cls, -1];
				if (_c isEqualType []) then {
					private _pick = "";
					{
						private _cand = _x;
						if (_pick == "" && {(_out findIf {_x isEqualType [] && {count _x > 0} && {(_x select 0) isEqualType ""} && {(_x select 0) == _cand}}) < 0}) then {_pick = _cand};
					} forEach _c;
					if (_pick != "") then {private _ne = +_e; _ne set [0, _pick]; _out pushBack _ne; _nCh = _nCh + 1} else {_nDrop = _nDrop + 1};
				} else {
					_out pushBack _e;
				};
			} forEach _old;
			if (_out isNotEqualTo [] && {_out isNotEqualTo _old}) then {
				missionNamespace setVariable [_k, _out];
				[10, _nCh] call VIOC_NARCO_fnc_stat;
				[11, _nDrop] call VIOC_NARCO_fnc_stat;
			};
		};
	} forEach ["WHEELED_SQ_LIGHT", "WHEELED_SQ_HEAVY", "TRACKED_SQ_LIGHT", "TRACKED_SQ_MEDIUM", "TRACKED_SQ_HEAVY", "AIR_SQ_FIGHTER", "AIR_SQ_BOMBER", "SQ_ANTI_AIR"];
};

//--- 5) ubase_ChDKZ_RHS.sqf (al final): vehiculos iniciales
VIOC_NARCO_fnc_base = {
	params ["_side"];
	if (!VIOC_NARCO_ON || {!(_side in [west, east])}) exitWith {};
	private _k = format ["CTI_%1_Vehicles_Startup", _side];
	private _cur = missionNamespace getVariable [_k, []];
	//--- solo si los vehiculos iniciales son los de la ChDKZ (este archivo los acaba de poner)
	if !(_cur isEqualType [] && {_cur isNotEqualTo []} && {(_cur findIf {!(_x isEqualType [] && {count _x > 0} && {((toLower (_x select 0)) find "rhsgref_ins") == 0})}) < 0}) exitWith {};
	private _l = [];
	{ private _c = _x select 0; if ([_c] call VIOC_NARCO_fnc_ok) then {_l pushBack [_c, []]} } forEach VIOC_NARCO_DATA_START;
	if (count _l >= 2) then {missionNamespace setVariable [_k, _l]};
};

//--- 6) Common\Config\Artillery\Artillery.sqf, antes de Set_Artillery: Hilux MLRS y Podnos, y el BM-21 del Este
VIOC_NARCO_fnc_artillery = {
	params ["_c", "_m", "_b", "_r"];
	if (!VIOC_NARCO_ON) exitWith {};
	{
		_x params ["_cls", "_mags", "_bursts", "_ranges"];
		if ([_cls] call VIOC_NARCO_fnc_ok && {(_c findIf {_x == _cls}) < 0}) then {
			_c pushBack _cls; _m pushBack _mags; _b pushBack _bursts; _r pushBack _ranges;
		};
	} forEach VIOC_NARCO_DATA_ARTY;
};

//--- 7) gear_RHS_ChDKZ.sqf, antes de VIOC_gear_extra: ropa del narco y armas NAR en la tienda (VIOC_gear_extra
//--- agrega despues sus cargadores y accesorios). Mismas reglas que VIOC_gear_extra: solo al armar la tienda
//--- (CTI_Init_Common), el primer nivel que ya usa la tienda, un uniforme solo si el bando puede vestirlo (modelSides)
//--- y nada que esta tienda u otra anterior ya tenga. Precio: uniforme x1, correaje x2, chaleco blindado x3, gorra x0.5,
//--- casco x1, gafas x0.5 de CTI_ECONOMY_PRIZE_EQUIPMENT; armas x1 de CTI_ECONOMY_PRIZE_WEAPONS.
VIOC_NARCO_fnc_gear = {
	params ["_side", "_c", "_u", "_p"];
	if (!VIOC_NARCO_ON || {isNil "CTI_Init_Common"}) exitWith {};
	private _t0 = 99;
	{ if (_x isEqualType 0) then {_t0 = _t0 min _x} } forEach _u;
	if (_t0 == 99) then {_t0 = 0};
	private _sid = [east, west, resistance, civilian] find _side;
	private _addOne = {
		params ["_cls", "_price"];
		if ((_c findIf {_x isEqualType "" && {_x == _cls}}) >= 0) exitWith {};
		if !(isNil {missionNamespace getVariable (toLower _cls)}) exitWith {};
		_c pushBack _cls; _u pushBack _t0; _p pushBack _price;
	};
	{
		_x params ["_key", "_l"];
		private _slot = (_key splitString "|") select 1;
		{
			_x params ["_cls", "", "", "_arm"];
			private _ok = isClass (configFile >> "CfgWeapons" >> _cls) || {isClass (configFile >> "CfgGlasses" >> _cls)};
			if (_ok && {_slot == "uniform"}) then {
				_ok = _sid in (getArray (configFile >> "CfgVehicles" >> (getText (configFile >> "CfgWeapons" >> _cls >> "ItemInfo" >> "uniformClass")) >> "modelSides"));
			};
			if (_ok) then {
				private _mult = switch (_slot) do {
					case "uniform": {1};
					case "vest": {[2, 3] select (_arm >= 8)};
					case "headgear": {[0.5, 1] select (_arm > 0)};
					default {0.5};
				};
				[_cls, [CTI_ECONOMY_PRIZE_EQUIPMENT, _t0, _mult] call CTI_CO_FNC_GetCalculatedItemPrize] call _addOne;
			};
		} forEach _l;
	} forEach VIOC_NARCO_DATA_SETS;
	{
		{
			_x params ["_cls"];
			if (isClass (configFile >> "CfgWeapons" >> _cls)) then {[_cls, [CTI_ECONOMY_PRIZE_WEAPONS, _t0, 1.0] call CTI_CO_FNC_GetCalculatedItemPrize] call _addOne};
		} forEach (_x select 1);
	} forEach VIOC_NARCO_DATA_NARPOOLS;
};

//--- 8) gear_start_config.sqf (al final): equipo inicial/por defecto de la ChDKZ
VIOC_NARCO_fnc_defaultGear = {
	params ["_side", "_var"];
	if (!VIOC_NARCO_ON) exitWith {false};
	private _mn = missionNamespace getVariable [format ["CTI_%1_MAINNATIONS", _side], [-1, -1]];
	if !(_mn isEqualType [] && {count _mn > 0} && {!isNil "CTI_CHDKZ_ID"} && {(_mn select 0) isEqualTo CTI_CHDKZ_ID}) exitWith {false};
	private _g = missionNamespace getVariable [_var, []];
	if !(_g isEqualType [] && {count _g > 2}) exitWith {false};
	VIOC_NARCO_DATA_DEFAULT params ["_un", "_ve", "_he"];
	private _cont = _g select 1;
	if (isClass (configFile >> "CfgWeapons" >> _un)) then {(_cont select 0) set [0, _un]};
	if (isClass (configFile >> "CfgWeapons" >> _ve)) then {(_cont select 1) set [0, _ve]};
	if (isClass (configFile >> "CfgWeapons" >> _he)) then {(_g select 2) set [0, _he]};
	missionNamespace setVariable [_var, _g];
	diag_log format ["VIOC_Narco: equipo por defecto %1: %2", _side, [_un, _ve, _he]];
	true
};

//--- 9) Ropa de un soldado ChDKZ (funciones de tropical_gear: cambio transaccional, contenido que cabe).
VIOC_NARCO_fnc_dress = {
	params ["_unit", "_role"];
	if (isNil "VIOC_TG_fnc_swapUniform" || {isNil "VIOC_TG_fnc_tryList"}) exitWith {false};
	private _cls = toLower typeOf _unit;
	private _isPilot = (_cls find "pilot") >= 0;
	private _isCrew = _isPilot || {_role == "crew"};
	private _isLead = _role == "leader";
	private _hasVest = (vest _unit) != "";
	//--- uniforme
	private _u = uniform _unit;
	private _lu = toLower _u;
	if (_u != "" && {(_lu find "ghillie") < 0}) then {
		private _okU = ((VIOC_NARCO_SETHAS getOrDefault ["NAR|uniform|fighter", createHashMap]) getOrDefault [_lu, false]) || {(VIOC_NARCO_SETHAS getOrDefault ["NAR|uniform|sicario", createHashMap]) getOrDefault [_lu, false]};
		if (!_okU || {random 1 < VIOC_NARCO_P_VAR}) then {
			private _key = if (_isCrew || {_isLead} || {random 1 >= VIOC_NARCO_P_FIGHTER}) then {"NAR|uniform|sicario"} else {"NAR|uniform|fighter"};
			private _other = ["NAR|uniform|sicario", "NAR|uniform|fighter"] select (_key == "NAR|uniform|sicario");
			private _mass = (loadUniform _unit) * ([_u] call VIOC_TG_fnc_cap);
			private _n = [VIOC_NARCO_SETS getOrDefault [_key, []], _u, _mass, 0] call VIOC_TG_fnc_tryList;
			if (_n == "" && {!_okU}) then {_n = [VIOC_NARCO_SETS getOrDefault [_other, []], _u, _mass, 0] call VIOC_TG_fnc_tryList};
			if (_n != "") then {
				if ([_unit, _n] call VIOC_TG_fnc_swapUniform) then {[8] call VIOC_NARCO_fnc_stat};
			} else {
				if (!_okU && {!_hasVest} && {!isNil "VIOC_TG_fnc_swapUniformSplit"}) then {
					private _nu = [VIOC_NARCO_SETS getOrDefault [_key, []]] call VIOC_TG_fnc_pick;
					private _nv = [VIOC_NARCO_SETS getOrDefault ["NAR|vest|light", []]] call VIOC_TG_fnc_pick;
					if ([_unit, _nu, _nv] call VIOC_TG_fnc_swapUniformSplit) then {[8, 2] call VIOC_NARCO_fnc_stat};
				};
			};
		};
	};
	//--- chaleco (los tripulantes y pilotos se quedan con el suyo)
	if (_hasVest && {!_isCrew}) then {
		private _v = vest _unit;
		private _lv = toLower _v;
		private _okV = ((VIOC_NARCO_SETHAS getOrDefault ["NAR|vest", createHashMap]) getOrDefault [_lv, false]) || {(VIOC_NARCO_SETHAS getOrDefault ["NAR|vest|boss", createHashMap]) getOrDefault [_lv, false]};
		if (!_okV || {random 1 < VIOC_NARCO_P_VAR}) then {
			private _key = ["NAR|vest", "NAR|vest|boss"] select _isLead;
			private _arm = [_v] call VIOC_TG_fnc_armor;
			private _mass = (loadVest _unit) * ([_v] call VIOC_TG_fnc_cap);
			private _n = [VIOC_NARCO_SETS getOrDefault [_key, []], _v, _mass, (_arm - 4) max 0] call VIOC_TG_fnc_tryList;
			if (_n == "" && {_isLead}) then {_n = [VIOC_NARCO_SETS getOrDefault ["NAR|vest", []], _v, _mass, (_arm - 4) max 0] call VIOC_TG_fnc_tryList};
			if (_n != "" && {[_unit, _n] call VIOC_TG_fnc_swapVest}) then {[8] call VIOC_NARCO_fnc_stat};
		};
	};
	//--- gorra (los cascos, los de tanquista y los de piloto no se tocan)
	private _h = headgear _unit;
	private _hKey = ["NAR|headgear", "NAR|headgear|lead"] select _isLead;
	if (_h == "") then {
		if (!_isCrew && {random 1 < VIOC_NARCO_P_HAT}) then {
			private _n = [VIOC_NARCO_SETS getOrDefault [_hKey, []], "", 0, 0] call VIOC_TG_fnc_tryList;
			if (_n != "" && {[_unit, _n] call VIOC_TG_fnc_swapHead}) then {[8] call VIOC_NARCO_fnc_stat};
		};
	} else {
		private _lh = toLower _h;
		if (!_isCrew && {([_h] call VIOC_TG_fnc_armor) <= 0} && {(_lh find "headphones") < 0}) then {
			private _okH = ((VIOC_NARCO_SETHAS getOrDefault ["NAR|headgear", createHashMap]) getOrDefault [_lh, false]) || {(VIOC_NARCO_SETHAS getOrDefault ["NAR|headgear|lead", createHashMap]) getOrDefault [_lh, false]};
			if (!_okH || {random 1 < VIOC_NARCO_P_VAR}) then {
				private _n = [VIOC_NARCO_SETS getOrDefault [_hKey, []], _h, 0, 0] call VIOC_TG_fnc_tryList;
				if (_n != "" && {[_unit, _n] call VIOC_TG_fnc_swapHead}) then {[8] call VIOC_NARCO_fnc_stat};
			};
		};
	};
	//--- mascara o gafas
	if ((goggles _unit) == "" && {!_isPilot} && {random 1 < VIOC_NARCO_P_MASK}) then {
		private _g = [VIOC_NARCO_SETS getOrDefault ["NAR|facewear", []]] call VIOC_TG_fnc_pick;
		if (_g != "") then {_unit addGoggles _g; if ((goggles _unit) != "") then {[8] call VIOC_NARCO_fnc_stat}};
	};
	true
};

//--- Common_CreateUnit.sqf, justo despues de ai_loadouts y antes de tropical_gear (que lo salta: marca "vioc_tg").
VIOC_NARCO_fnc_unit = {
	params [["_unit", objNull, [objNull]]];
	if (!VIOC_NARCO_ON) exitWith {false};
	if (isNull _unit || {!local _unit} || {!alive _unit} || {isPlayer _unit} || {!(_unit isKindOf "CAManBase")}) exitWith {false};
	if (_unit getVariable ["vioc_specops", false] || {_unit getVariable ["vioc_nar", false]}) exitWith {false};
	if !((toLower getText (configFile >> "CfgVehicles" >> typeOf _unit >> "faction")) in VIOC_NARCO_FACTIONS) exitWith {false};
	_unit setVariable ["vioc_nar", true];
	private _role = "rifle";
	if (!isNil "VIOC_LO_fnc_classInfo") then {_role = ([typeOf _unit] call VIOC_LO_fnc_classInfo) select 1};
	if (_role == "none") exitWith {false};
	if ([_unit, _role] call VIOC_NARCO_fnc_dress) then {
		[7] call VIOC_NARCO_fnc_stat;
		_unit setVariable ["vioc_tg", true];	//--- tropical_gear ya no lo viste otra vez
	};
	true
};

//--- VIOC_specops.sqf, al crear un soldado de operaciones especiales (no pasan por Common_CreateUnit)
VIOC_NARCO_fnc_dressSO = {
	params [["_unit", objNull, [objNull]]];
	if (!VIOC_NARCO_ON || {isNull _unit}) exitWith {false};
	if !((toLower getText (configFile >> "CfgVehicles" >> typeOf _unit >> "faction")) in VIOC_NARCO_FACTIONS) exitWith {false};
	if (_unit getVariable ["vioc_nar", false]) exitWith {false};
	_unit setVariable ["vioc_nar", true];
	private _role = "rifle";
	if (!isNil "VIOC_LO_fnc_classInfo") then {_role = ([typeOf _unit] call VIOC_LO_fnc_classInfo) select 1};
	if ([_unit, _role] call VIOC_NARCO_fnc_dress) then {[7] call VIOC_NARCO_fnc_stat};
	true
};

//--- 10) VIOC_specops.sqf: paquetes del narco (se agregan a VIOC_SO_PACKAGES antes de comprobar sus clases)
VIOC_NARCO_fnc_soPackages = {
	if (!VIOC_NARCO_ON) exitWith {[]};
	VIOC_NARCO_DATA_SO apply {createHashMapFromArray _x}
};

//--- 11) Init_Common, antes de pylons.sqf (despues de units_extra_dlc y contemporary_assets): el bando narco no
//--- vende los vehiculos militares vanilla (B_/O_/I_) que agrega units_extra_dlc; quedan las lanchas propias.
VIOC_NARCO_fnc_postAll = {
	if (!VIOC_NARCO_ON || {isNil "CTI_CHDKZ_ID"}) exitWith {};
	private _side = (missionNamespace getVariable ["CTI_CHDKZ_SIDE", -1]) call CTI_CO_FNC_GetSideFromID;
	private _mn = missionNamespace getVariable [format ["CTI_%1_MAINNATIONS", _side], [-1, -1]];
	if !(_mn isEqualType [] && {count _mn > 0} && {(_mn select 0) isEqualTo CTI_CHDKZ_ID}) exitWith {};
	private _keep = createHashMap;
	{ { if (_x isEqualType "" && {_x != ""}) then {_keep set [toLower _x, true]} } forEach [_x select 0, _x select 1] } forEach VIOC_NARCO_DATA_NAVAL;
	{ { if (_x isEqualType "") then {_keep set [toLower _x, true]} } forEach _x } forEach (missionNamespace getVariable [format ["VIOC_NARCO_AUTHOR_%1", _side], []]);
	{
		private _k = format ["CTI_%1_%2Units", _side, _x];
		private _l = missionNamespace getVariable [_k, []];
		if (_l isEqualType []) then {
			//--- fuera: clases vanilla/Creator DLC militares (prefijo B_/O_/I_/EF_ y bando 0-2 en la configuracion) que no
			//--- puso el autor ni este parche
			private _out = _l select {
				private _lc = if (_x isEqualType "") then {toLower _x} else {""};
				(_lc == "") || {_keep getOrDefault [_lc, false]} || {(["b_", "o_", "i_", "ef_"] findIf {(_lc find _x) == 0}) < 0} || {!((getNumber (configFile >> "CfgVehicles" >> _x >> "side")) in [0, 1, 2])} || {_x isKindOf "CAManBase"}
			};
			if (count _out != count _l) then {
				[9, (count _l) - (count _out)] call VIOC_NARCO_fnc_stat;
				missionNamespace setVariable [_k, _out];
			};
		};
	} forEach [CTI_LIGHT, CTI_HEAVY, CTI_AIR, CTI_NAVAL];
};

//--- Listas finales (solo clases que existen) y la nacion NAR de ai_loadouts
VIOC_NARCO_SETS = createHashMap;
VIOC_NARCO_SETHAS = createHashMap;
{
	_x params ["_k", "_l"];
	private _ok = _l select {isClass (configFile >> "CfgWeapons" >> (_x select 0)) || {isClass (configFile >> "CfgGlasses" >> (_x select 0))}};
	if (_ok isNotEqualTo []) then {
		VIOC_NARCO_SETS set [_k, _ok apply {[_x select 0, _x select 1]}];
		private _h = createHashMap;
		{ _h set [toLower (_x select 0), true] } forEach _ok;
		VIOC_NARCO_SETHAS set [_k, _h];
	};
} forEach VIOC_NARCO_DATA_SETS;
if (VIOC_NARCO_ON && {!isNil "VIOC_LOADOUT_POOLS"} && {!isNil "VIOC_LO_FACNAT"}) then {
	{
		_x params ["_role", "_list"];
		private _ok = _list select {isClass (configFile >> "CfgWeapons" >> (_x select 0))};
		if (_ok isNotEqualTo []) then {VIOC_LOADOUT_POOLS set ["NAR|" + _role, _ok]};
	} forEach VIOC_NARCO_DATA_NARPOOLS;
	{ VIOC_LO_FACNAT set [_x, "NAR"] } forEach VIOC_NARCO_FACTIONS;
	if (!isNil "VIOC_LO_KEEP") then {VIOC_LO_KEEP set ["NAR", 0.15]};
	if (!isNil "VIOC_LO_OPTF") then {VIOC_LO_OPTF set ["NAR", 0.2]};
	if (!isNil "VIOC_LO_OPTICS") then {
		{ private _o = VIOC_LO_OPTICS getOrDefault ["GUE|" + _x, []]; if (_o isNotEqualTo []) then {VIOC_LO_OPTICS set ["NAR|" + _x, _o]} } forEach ["cqb", "mid", "dmr"];
	};
};

